#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} custom_sem_t;

void custom_sem_init(custom_sem_t *sem, int value) {
    sem->count = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

void custom_sem_wait(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->count <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);
}

void custom_sem_post(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

void custom_sem_destroy(custom_sem_t *sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

custom_sem_t sem;

void *worker(void *arg) {
    long id = (long)arg;
    custom_sem_wait(&sem);
    printf("Thread %ld entered critical section\n", id);
    custom_sem_post(&sem);
    return NULL;
}

int main(void) {
    pthread_t threads[4];
    custom_sem_init(&sem, 2);

    for (long i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, worker, (void *)i);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    custom_sem_destroy(&sem);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} custom_sem_t;

void custom_sem_init(custom_sem_t *sem, int value) {
    sem->count = value;
    pthread_mutex_init(&sem->mutex, NULL);
    pthread_cond_init(&sem->cond, NULL);
}

void custom_sem_wait(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->count <= 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->count--;
    pthread_mutex_unlock(&sem->mutex);
}

int custom_sem_trywait(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    if (sem->count > 0) {
        sem->count--;
        pthread_mutex_unlock(&sem->mutex);
        return 0;
    }
    pthread_mutex_unlock(&sem->mutex);
    return -1;
}

void custom_sem_post(custom_sem_t *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->count++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

void custom_sem_destroy(custom_sem_t *sem) {
    pthread_mutex_destroy(&sem->mutex);
    pthread_cond_destroy(&sem->cond);
}

custom_sem_t sem;

void *worker(void *arg) {
    long id = (long)arg;
    if (id % 2 == 0) {
        custom_sem_wait(&sem);
        printf("Thread %ld acquired via wait\n", id);
        custom_sem_post(&sem);
    } else {
        if (custom_sem_trywait(&sem) == 0) {
            printf("Thread %ld acquired via trywait\n", id);
            custom_sem_post(&sem);
        } else {
            printf("Thread %ld trywait failed\n", id);
        }
    }
    return NULL;
}

int main(void) {
    pthread_t threads[4];
    custom_sem_init(&sem, 1);

    for (long i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, worker, (void *)i);
    }
    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }

    custom_sem_destroy(&sem);
    return 0;
}

