    pthread_mutex_init(&h->lock, NULL);
    pthread_cond_init(&h->cond, NULL);
    h->h_count = 0;
    h->o_count = 0;
}

void h2o_destroy(h2o_t *h) {
    pthread_mutex_destroy(&h->lock);
    pthread_cond_destroy(&h->cond);
}

void *hydrogen(void *arg) {
    (void)arg;
    pthread_mutex_lock(&h2o.lock);
    h2o.h_count++;
    while (h2o.h_count < 2 || h2o.o_count < 1) {
        pthread_cond_wait(&h2o.cond, &h2o.lock);
    }
    printf("H");
    if (h2o.h_count == 2 && h2o.o_count >= 1) {
        // Last hydrogen in generation triggers unblock for others
        pthread_cond_broadcast(&h2o.cond);
    }
    h2o.h_count--;
    pthread_mutex_unlock(&h2o.lock);
    return NULL;
}

void *oxygen(void *arg) {
    (void)arg;
    pthread_mutex_lock(&h2o.lock);
    h2o.o_count++;
    while (h2o.h_count < 2) {
        pthread_cond_wait(&h2o.cond, &h2o.lock);
    }
    printf("O\n");
    h2o.o_count--;
    pthread_cond_broadcast(&h2o.cond);
    pthread_mutex_unlock(&h2o.lock);
    return NULL;
}

