#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int data;
    struct node *next;
} node_t;

typedef struct {
    node_t *head;
    node_t *tail;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} queue_t;

void queue_init(queue_t *q) {
    q->head = NULL;
    q->tail = NULL;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
}

void queue_enqueue(queue_t *q, int val) {
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data = val;
    new_node->next = NULL;

    pthread_mutex_lock(&q->lock);
    if (q->tail) {
        q->tail->next = new_node;
    } else {
        q->head = new_node;
    }
    q->tail = new_node;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
}

int queue_dequeue(queue_t *q) {
    pthread_mutex_lock(&q->lock);
    while (q->head == NULL) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    node_t *temp = q->head;
    int val = temp->data;
    q->head = q->head->next;
    if (q->head == NULL) {
        q->tail = NULL;
    }
    pthread_mutex_unlock(&q->lock);
    free(temp);
    return val;
}

void queue_destroy(queue_t *q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->cond);
}

queue_t q;

void *producer(void *arg) {
    (void)arg;
    for (int i = 0; i < 5; i++) {
        queue_enqueue(&q, i);
    }
    return NULL;
}

void *consumer(void *arg) {
    (void)arg;
    for (int i = 0; i < 5; i++) {
        int val = queue_dequeue(&q);
        printf("Dequeued: %d\n", val);
    }
    return NULL;
}

int main(void) {
    queue_init(&q);
    pthread_t p, c;
    pthread_create(&p, NULL, producer, NULL);
    pthread_create(&c, NULL, consumer, NULL);
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    queue_destroy(&q);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct node {
    int data;
    struct node *next;
} node_t;

typedef struct {
    node_t *head;
    node_t *tail;
    int is_shutdown;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} queue_t;

void queue_init(queue_t *q) {
    q->head = NULL;
    q->tail = NULL;
    q->is_shutdown = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
}

int queue_enqueue(queue_t *q, int val) {
    pthread_mutex_lock(&q->lock);
    if (q->is_shutdown) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data = val;
    new_node->next = NULL;
    if (q->tail) {
        q->tail->next = new_node;
    } else {
        q->head = new_node;
    }
    q->tail = new_node;
    pthread_cond_signal(&q->cond);
    pthread_mutex_unlock(&q->lock);
    return 0;
}

int queue_dequeue(queue_t *q, int *out) {
    pthread_mutex_lock(&q->lock);
    while (q->head == NULL && !q->is_shutdown) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    if (q->head == NULL && q->is_shutdown) {
        pthread_mutex_unlock(&q->lock);
        return -1;
    }
    node_t *temp = q->head;
    *out = temp->data;
    q->head = q->head->next;
    if (q->head == NULL) {
        q->tail = NULL;
    }
    pthread_mutex_unlock(&q->lock);
    free(temp);
    return 0;
}

void queue_shutdown(queue_t *q) {
    pthread_mutex_lock(&q->lock);
    q->is_shutdown = 1;
    pthread_cond_broadcast(&q->cond);
    pthread_mutex_unlock(&q->lock);
}

void queue_destroy(queue_t *q) {
    pthread_mutex_destroy(&q->lock);
    pthread_cond_destroy(&q->cond);
}

queue_t q;

void *consumer(void *arg) {
    (void)arg;
    int val;
    while (queue_dequeue(&q, &val) == 0) {
        printf("Consumed %d\n", val);
    }
    printf("Consumer unblocked due to shutdown\n");
    return NULL;
}

int main(void) {
    queue_init(&q);
    pthread_t c;
    pthread_create(&c, NULL, consumer, NULL);

    queue_enqueue(&q, 42);
    queue_shutdown(&q);

    pthread_join(c, NULL);
    queue_destroy(&q);
    return 0;
}

#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>

#define BUFFER_SIZE 5

typedef struct {
    int buffer[BUFFER_SIZE];
    int in;
    int out;
    sem_t empty;
    sem_t full;
    pthread_mutex_t lock;
} bounded_buffer_t;

bounded_buffer_t bb;

void bb_init(bounded_buffer_t *b) {
    b->in = 0;
    b->out = 0;
    sem_init(&b->empty, 0, BUFFER_SIZE);
    sem_init(&b->full, 0, 0);
    pthread_mutex_init(&b->lock, NULL);
}

void bb_destroy(bounded_buffer_t *b) {
    sem_destroy(&b->empty);
    sem_destroy(&b->full);
    pthread_mutex_destroy(&b->lock);
}

void *producer(void *arg) {
    (void)arg;
    for (int i = 0; i < 10; i++) {
        sem_wait(&bb.empty);
        pthread_mutex_lock(&bb.lock);
        bb.buffer[bb.in] = i;
        bb.in = (bb.in + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&bb.lock);
        sem_post(&bb.full);
    }
    return NULL;
}

void *consumer(void *arg) {
    (void)arg;
    for (int i = 0; i < 10; i++) {
        sem_wait(&bb.full);
        pthread_mutex_lock(&bb.lock);
        int item = bb.buffer[bb.out];
        bb.out = (bb.out + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&bb.lock);
        sem_post(&bb.empty);
        printf("Consumed: %d\n", item);
    }
    return NULL;
}

int main(void) {
    bb_init(&bb);
    pthread_t p, c;
    pthread_create(&p, NULL, producer, NULL);
    pthread_create(&c, NULL, consumer, NULL);
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    bb_destroy(&bb);
    return 0;
}

