#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define CAPACITY 5
#define TOTAL_ITEMS 40

typedef struct {
    int buffer[CAPACITY];
    int head;
    int tail;
    int count;
    int produced_count;
    int consumed_count;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} bounded_buffer_t;

static bounded_buffer_t bb;

void *producer(void *arg) {
    (void)arg;
    while (1) {
        pthread_mutex_lock(&bb.mutex);
        if (bb.produced_count >= TOTAL_ITEMS) {
            pthread_mutex_unlock(&bb.mutex);
            break;
        }
        while (bb.count == CAPACITY) {
            pthread_cond_wait(&bb.not_full, &bb.mutex);
        }
        int item = ++bb.produced_count;
        bb.buffer[bb.tail] = item;
        bb.tail = (bb.tail + 1) % CAPACITY;
        bb.count++;
        pthread_cond_signal(&bb.not_empty);
        pthread_mutex_unlock(&bb.mutex);
    }
    return NULL;
}

void *consumer(void *arg) {
    (void)arg;
    while (1) {
        pthread_mutex_lock(&bb.mutex);
        while (bb.count == 0 && bb.consumed_count < TOTAL_ITEMS) {
            pthread_cond_wait(&bb.not_empty, &bb.mutex);
        }
        if (bb.consumed_count >= TOTAL_ITEMS) {
            pthread_mutex_unlock(&bb.mutex);
            break;
        }
        int item = bb.buffer[bb.head];
        bb.head = (bb.head + 1) % CAPACITY;
        bb.count--;
        bb.consumed_count++;
        (void)item;
        pthread_cond_signal(&bb.not_full);
        if (bb.consumed_count >= TOTAL_ITEMS) {
            pthread_cond_broadcast(&bb.not_empty);
        }
        pthread_mutex_unlock(&bb.mutex);
    }
    return NULL;
}

int main(void) {
    pthread_t prods[2], cons[2];
    bb.head = 0;
    bb.tail = 0;
    bb.count = 0;
    bb.produced_count = 0;
    bb.consumed_count = 0;
    pthread_mutex_init(&bb.mutex, NULL);
    pthread_cond_init(&bb.not_empty, NULL);
    pthread_cond_init(&bb.not_full, NULL);

    for (int i = 0; i < 2; i++) pthread_create(&prods[i], NULL, producer, NULL);
    for (int i = 0; i < 2; i++) pthread_create(&cons[i], NULL, consumer, NULL);

    for (int i = 0; i < 2; i++) pthread_join(prods[i], NULL);
    for (int i = 0; i < 2; i++) pthread_join(cons[i], NULL);

    pthread_mutex_destroy(&bb.mutex);
    pthread_cond_destroy(&bb.not_empty);
    pthread_cond_destroy(&bb.not_full);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define CAPACITY 4
#define NUM_PRODUCERS 2
#define NUM_CONSUMERS 3
#define ITEMS_PER_PROD 15
#define POISON_PILL (-1)

typedef struct {
    int data[CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} queue_t;

static queue_t q;

static void enqueue(int val) {
    pthread_mutex_lock(&q.lock);
    while (q.count == CAPACITY) {
        pthread_cond_wait(&q.not_full, &q.lock);
    }
    q.data[q.tail] = val;
    q.tail = (q.tail + 1) % CAPACITY;
    q.count++;
    pthread_cond_signal(&q.not_empty);
    pthread_mutex_unlock(&q.lock);
}

static int dequeue(void) {
    pthread_mutex_lock(&q.lock);
    while (q.count == 0) {
        pthread_cond_wait(&q.not_empty, &q.lock);
    }
    int val = q.data[q.head];
    q.head = (q.head + 1) % CAPACITY;
    q.count--;
    pthread_cond_signal(&q.not_full);
    pthread_mutex_unlock(&q.lock);
    return val;
}

void *producer(void *arg) {
    long id = (long)arg;
    for (int i = 1; i <= ITEMS_PER_PROD; i++) {
        enqueue((int)(id * 1000 + i));
    }
    return NULL;
}

void *consumer(void *arg) {
    (void)arg;
    while (1) {
        int val = dequeue();
        if (val == POISON_PILL) {
            break;
        }
    }
    return NULL;
}

int main(void) {
    pthread_t prods[NUM_PRODUCERS];
    pthread_t cons[NUM_CONSUMERS];

    q.head = 0;
    q.tail = 0;
    q.count = 0;
    pthread_mutex_init(&q.lock, NULL);
    pthread_cond_init(&q.not_empty, NULL);
    pthread_cond_init(&q.not_full, NULL);

    for (long i = 0; i < NUM_PRODUCERS; i++) pthread_create(&prods[i], NULL, producer, (void *)i);
    for (long i = 0; i < NUM_CONSUMERS; i++) pthread_create(&cons[i], NULL, consumer, (void *)i);

    for (int i = 0; i < NUM_PRODUCERS; i++) pthread_join(prods[i], NULL);

    for (int i = 0; i < NUM_CONSUMERS; i++) enqueue(POISON_PILL);

    for (int i = 0; i < NUM_CONSUMERS; i++) pthread_join(cons[i], NULL);

    pthread_mutex_destroy(&q.lock);
    pthread_cond_destroy(&q.not_empty);
    pthread_cond_destroy(&q.not_full);
    return 0;
}

#include <stdio.h>
#include <pthread.h>

#define NUM_ACCOUNTS 4
#define NUM_THREADS 4
#define TRANSFERS_PER_THREAD 1000

typedef struct {
    int id;
    int balance;
    pthread_mutex_t lock;
} account_t;

static account_t accounts[NUM_ACCOUNTS];

static void transfer(account_t *from, account_t *to, int amount) {
    if (from == to) return;

    account_t *first = from->id < to->id ? from : to;
    account_t *second = from->id < to->id ? to : from;

    pthread_mutex_lock(&first->lock);
    pthread_mutex_lock(&second->lock);

    if (from->balance >= amount) {
        from->balance -= amount;
        to->balance += amount;
    }

    pthread_mutex_unlock(&second->lock);
    pthread_mutex_unlock(&first->lock);
}

void *worker(void *arg) {
    long tid = (long)arg;
    for (int i = 0; i < TRANSFERS_PER_THREAD; i++) {
        int src = (int)((tid + i) % NUM_ACCOUNTS);
        int dst = (int)((tid + i + 1) % NUM_ACCOUNTS);
        transfer(&accounts[src], &accounts[dst], 10);
    }
    return NULL;
}

int main(void) {
    pthread_t threads[NUM_THREADS];
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        accounts[i].id = i;
        accounts[i].balance = 5000;
        pthread_mutex_init(&accounts[i].lock, NULL);
    }

    for (long i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker, (void *)i);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    int total = 0;
    for (int i = 0; i < NUM_ACCOUNTS; i++) {
        total += accounts[i].balance;
        pthread_mutex_destroy(&accounts[i].lock);
    }
    printf("Total balance: %d\n", total);
    return 0;
}

