#include <stdio.h>
#include <pthread.h>

#define TARGET 100

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int value;
    int turn; /* 0 for ping, 1 for pong */
    int stop;
} shared_state_t;

static shared_state_t state;

void *ping_thread(void *arg) {
    (void)arg;
    while (1) {
        pthread_mutex_lock(&state.lock);
        while (state.turn != 0 && !state.stop) {
            pthread_cond_wait(&state.cond, &state.lock);
        }
        if (state.stop) {
            pthread_mutex_unlock(&state.lock);
            break;
        }
        state.value += 1;
        printf("Ping: %d\n", state.value);
        if (state.value >= TARGET) {
            state.stop = 1;
            state.turn = 1;
            pthread_cond_signal(&state.cond);
            pthread_mutex_unlock(&state.lock);
            break;
        }
        state.turn = 1;
        pthread_cond_signal(&state.cond);
        pthread_mutex_unlock(&state.lock);
    }
    return NULL;
}

void *pong_thread(void *arg) {
    (void)arg;
    while (1) {
        pthread_mutex_lock(&state.lock);
        while (state.turn != 1 && !state.stop) {
            pthread_cond_wait(&state.cond, &state.lock);
        }
        if (state.stop) {
            pthread_mutex_unlock(&state.lock);
            break;
        }
        state.value *= 2;
        printf("Pong: %d\n", state.value);
        if (state.value >= TARGET) {
            state.stop = 1;
            state.turn = 0;
            pthread_cond_signal(&state.cond);
            pthread_mutex_unlock(&state.lock);
            break;
        }
        state.turn = 0;
        pthread_cond_signal(&state.cond);
        pthread_mutex_unlock(&state.lock);
    }
    return NULL;
}

