    pthread_t t1, t2;
    state.value = 1;
    state.turn = 0;
    state.stop = 0;
    pthread_mutex_init(&state.lock, NULL);
    pthread_cond_init(&state.cond, NULL);

    pthread_create(&t1, NULL, ping_thread, NULL);
    pthread_create(&t2, NULL, pong_thread, NULL);

    pthread_join(t1, NULL);
    pthread_join(t2, NULL);

    pthread_mutex_destroy(&state.lock);
    pthread_cond_destroy(&state.cond);
    return 0;
}

#include <stdio.h>
#include <pthread.h>

#define NUM_CHAIRS 3
#define TOTAL_CUSTOMERS 8

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t barber_cond;
    pthread_cond_t customer_cond;
    int waiting_customers;
    int served_count;
    int customer_done;
} shop_t;

static shop_t shop;

void *barber(void *arg) {
    (void)arg;
    while (1) {
        pthread_mutex_lock(&shop.lock);
        while (shop.waiting_customers == 0 && shop.served_count < TOTAL_CUSTOMERS) {
            pthread_cond_wait(&shop.barber_cond, &shop.lock);
        }
        if (shop.served_count >= TOTAL_CUSTOMERS && shop.waiting_customers == 0) {
            pthread_mutex_unlock(&shop.lock);
            break;
        }
        shop.waiting_customers--;
        shop.customer_done = 0;
        pthread_cond_signal(&shop.customer_cond);
        while (!shop.customer_done) {
            pthread_cond_wait(&shop.barber_cond, &shop.lock);
        }
        pthread_mutex_unlock(&shop.lock);
    }
    return NULL;
}

void *customer(void *arg) {
    (void)arg;
    pthread_mutex_lock(&shop.lock);
    if (shop.waiting_customers < NUM_CHAIRS) {
        shop.waiting_customers++;
        pthread_cond_signal(&shop.barber_cond);
        pthread_cond_wait(&shop.customer_cond, &shop.lock);
        shop.served_count++;
        shop.customer_done = 1;
        pthread_cond_signal(&shop.barber_cond);
    } else {
        shop.served_count++;
        if (shop.served_count == TOTAL_CUSTOMERS && shop.waiting_customers == 0) {
            pthread_cond_signal(&shop.barber_cond);
        }
    }
    pthread_mutex_unlock(&shop.lock);
    return NULL;
}

int main(void) {
    pthread_t b_thread;
    pthread_t c_threads[TOTAL_CUSTOMERS];

    pthread_mutex_init(&shop.lock, NULL);
    pthread_cond_init(&shop.barber_cond, NULL);
    pthread_cond_init(&shop.customer_cond, NULL);
    shop.waiting_customers = 0;
    shop.served_count = 0;
    shop.customer_done = 0;

    pthread_create(&b_thread, NULL, barber, NULL);
    for (int i = 0; i < TOTAL_CUSTOMERS; i++) {
        pthread_create(&c_threads[i], NULL, customer, NULL);
    }

    for (int i = 0; i < TOTAL_CUSTOMERS; i++) {
        pthread_join(c_threads[i], NULL);
    }
    pthread_join(b_thread, NULL);

    pthread_mutex_destroy(&shop.lock);
    pthread_cond_destroy(&shop.barber_cond);
    pthread_cond_destroy(&shop.customer_cond);
    return 0;
}

#include <stdio.h>
