    int waiting;
    int chair_in_use;
    int closing;
    int barber_finished;
} barber_shop_t;

static barber_shop_t shop;

void *barber_thread(void *arg) {
    (void)arg;
    pthread_mutex_lock(&shop.lock);
    while (1) {
        while (shop.waiting == 0 && !shop.closing) {
            pthread_cond_wait(&shop.cond_barber, &shop.lock);
        }
        if (shop.waiting == 0 && shop.closing) {
            shop.barber_finished = 1;
            break;
        }
        shop.waiting--;
        shop.chair_in_use = 1;
        pthread_cond_signal(&shop.cond_cust);
        while (shop.chair_in_use) {
            pthread_cond_wait(&shop.cond_barber, &shop.lock);
        }
    }
    pthread_mutex_unlock(&shop.lock);
    return NULL;
}

void *customer_thread(void *arg) {
    (void)arg;
    pthread_mutex_lock(&shop.lock);
    if (!shop.closing && shop.waiting < NUM_CHAIRS) {
        shop.waiting++;
        pthread_cond_signal(&shop.cond_barber);
        while (!shop.chair_in_use) {
            pthread_cond_wait(&shop.cond_cust, &shop.lock);
        }
        shop.chair_in_use = 0;
        pthread_cond_signal(&shop.cond_barber);
    }
    pthread_mutex_unlock(&shop.lock);
    return NULL;
}

