    pthread_cond_init(&shop.cond_barber, NULL);
    pthread_cond_init(&shop.cond_cust, NULL);
    shop.waiting = 0;
    shop.chair_in_use = 0;
    shop.closing = 0;
    shop.barber_finished = 0;

    pthread_create(&b_tid, NULL, barber_thread, NULL);
    for (int i = 0; i < TOTAL_CUSTOMERS; i++) {
        pthread_create(&c_tids[i], NULL, customer_thread, NULL);
    }

    for (int i = 0; i < TOTAL_CUSTOMERS; i++) {
        pthread_join(c_tids[i], NULL);
    }

    pthread_mutex_lock(&shop.lock);
    shop.closing = 1;
    pthread_cond_signal(&shop.cond_barber);
    pthread_mutex_unlock(&shop.lock);

    pthread_join(b_tid, NULL);

    pthread_mutex_destroy(&shop.lock);
    pthread_cond_destroy(&shop.cond_barber);
    pthread_cond_destroy(&shop.cond_cust);
    return 0;
}

