#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <unistd.h>

#define CAPACITY 3
#define NUM_CARS 7

typedef struct {
    pthread_mutex_t mtx;
    pthread_cond_t cond;
    bool slot_taken[CAPACITY];
} parking_lot_t;

static parking_lot_t lot;

static void *car_thread(void *arg) {
    long id = (long)arg;
    int assigned_slot = -1;

    pthread_mutex_lock(&lot.mtx);
    while (1) {
        for (int i = 0; i < CAPACITY; i++) {
            if (!lot.slot_taken[i]) {
                lot.slot_taken[i] = true;
                assigned_slot = i;
                break;
            }
        }
        if (assigned_slot != -1) {
            break;
        }
        pthread_cond_wait(&lot.cond, &lot.mtx);
    }
    printf("Car %ld parked in stall #%d\n", id, assigned_slot);
    pthread_mutex_unlock(&lot.mtx);

    usleep(10000);

    pthread_mutex_lock(&lot.mtx);
    lot.slot_taken[assigned_slot] = false;
    printf("Car %ld vacated stall #%d\n", id, assigned_slot);
    pthread_cond_signal(&lot.cond);
    pthread_mutex_unlock(&lot.mtx);

    return NULL;
}

int main(void) {
    pthread_mutex_init(&lot.mtx, NULL);
    pthread_cond_init(&lot.cond, NULL);
    for (int i = 0; i < CAPACITY; i++) {
        lot.slot_taken[i] = false;
    }

    pthread_t cars[NUM_CARS];
    for (long i = 0; i < NUM_CARS; i++) {
        pthread_create(&cars[i], NULL, car_thread, (void *)i);
    }

    for (int i = 0; i < NUM_CARS; i++) {
        pthread_join(cars[i], NULL);
    }

    pthread_mutex_destroy(&lot.mtx);
    pthread_cond_destroy(&lot.cond);
    return 0;
}

#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <sched.h>
#include <assert.h>

#define NUM_THREADS 4
#define ITERS_PER_THREAD 50000

typedef struct {
    bool locked;
} custom_spinlock_t;

static void spinlock_init(custom_spinlock_t *lock) {
    __atomic_clear(&lock->locked, __ATOMIC_RELAXED);
}

static void spinlock_acquire(custom_spinlock_t *lock) {
    while (__atomic_test_and_set(&lock->locked, __ATOMIC_ACQUIRE)) {
        sched_yield();
    }
}

static void spinlock_release(custom_spinlock_t *lock) {
    __atomic_clear(&lock->locked, __ATOMIC_RELEASE);
}

static custom_spinlock_t lock;
static long shared_counter = 0;

static void *worker(void *arg) {
    (void)arg;
    for (int i = 0; i < ITERS_PER_THREAD; i++) {
        spinlock_acquire(&lock);
        shared_counter++;
        spinlock_release(&lock);
    }
    return NULL;
}

int main(void) {
    spinlock_init(&lock);
    pthread_t threads[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    assert(shared_counter == NUM_THREADS * ITERS_PER_THREAD);
    printf("Final counter: %ld (expected: %d)\n", shared_counter, NUM_THREADS * ITERS_PER_THREAD);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <sched.h>
#include <assert.h>

#define NUM_THREADS 4
#define ITEMS_PER_THREAD 1000

typedef struct {
    bool locked;
} ttas_spinlock_t;

static void ttas_init(ttas_spinlock_t *s) {
    __atomic_clear(&s->locked, __ATOMIC_RELAXED);
}

static void ttas_lock(ttas_spinlock_t *s) {
    while (1) {
        while (__atomic_load_n(&s->locked, __ATOMIC_RELAXED)) {
            sched_yield();
        }
        if (!__atomic_test_and_set(&s->locked, __ATOMIC_ACQUIRE)) {
            break;
        }
    }
}

static void ttas_unlock(ttas_spinlock_t *s) {
    __atomic_clear(&s->locked, __ATOMIC_RELEASE);
}

typedef struct node {
    int val;
    struct node *next;
} node_t;

static ttas_spinlock_t list_lock;
static node_t *head = NULL;

static void *producer(void *arg) {
    (void)arg;
    for (int i = 0; i < ITEMS_PER_THREAD; i++) {
        node_t *n = malloc(sizeof(*n));
        assert(n != NULL);
        n->val = i;

        ttas_lock(&list_lock);
        n->next = head;
        head = n;
        ttas_unlock(&list_lock);
    }
    return NULL;
}

int main(void) {
    ttas_init(&list_lock);
    pthread_t th[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&th[i], NULL, producer, NULL);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(th[i], NULL);
    }

    int count = 0;
    node_t *curr = head;
    while (curr) {
        node_t *tmp = curr;
        curr = curr->next;
        free(tmp);
        count++;
    }

    assert(count == NUM_THREADS * ITEMS_PER_THREAD);
    printf("Successfully verified and freed %d nodes.\n", count);
    return 0;
}

#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

#define NUM_READERS 4
#define NUM_WRITERS 2
#define WRITER_OPS 3
#define READER_OPS 5

typedef struct {
    pthread_mutex_t mtx;
    pthread_cond_t read_cv;
    pthread_cond_t write_cv;
    int active_readers;
    int active_writers;
    int waiting_writers;
} rwlock_wp_t;

static rwlock_wp_t rw;
static int shared_data = 0;

static void rw_init(rwlock_wp_t *l) {
    pthread_mutex_init(&l->mtx, NULL);
    pthread_cond_init(&l->read_cv, NULL);
    pthread_cond_init(&l->write_cv, NULL);
    l->active_readers = 0;
    l->active_writers = 0;
    l->waiting_writers = 0;
}

static void rw_rdlock(rwlock_wp_t *l) {
    pthread_mutex_lock(&l->mtx);
    while (l->active_writers > 0 || l->waiting_writers > 0) {
        pthread_cond_wait(&l->read_cv, &l->mtx);
    }
    l->active_readers++;
    pthread_mutex_unlock(&l->mtx);
}

static void rw_rdunlock(rwlock_wp_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->active_readers--;
    if (l->active_readers == 0 && l->waiting_writers > 0) {
        pthread_cond_signal(&l->write_cv);
    }
    pthread_mutex_unlock(&l->mtx);
}

static void rw_wrlock(rwlock_wp_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->waiting_writers++;
    while (l->active_readers > 0 || l->active_writers > 0) {
        pthread_cond_wait(&l->write_cv, &l->mtx);
    }
    l->waiting_writers--;
    l->active_writers = 1;
    pthread_mutex_unlock(&l->mtx);
}

static void rw_wrunlock(rwlock_wp_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->active_writers = 0;
    if (l->waiting_writers > 0) {
        pthread_cond_signal(&l->write_cv);
    } else {
        pthread_cond_broadcast(&l->read_cv);
    }
    pthread_mutex_unlock(&l->mtx);
}

static void *reader_thread(void *arg) {
    (void)arg;
    for (int i = 0; i < READER_OPS; i++) {
        rw_rdlock(&rw);
        int val = shared_data;
        (void)val;
        usleep(2000);
        rw_rdunlock(&rw);
        usleep(1000);
    }
    return NULL;
}

static void *writer_thread(void *arg) {
    (void)arg;
    for (int i = 0; i < WRITER_OPS; i++) {
        rw_wrlock(&rw);
        shared_data++;
        usleep(3000);
        rw_wrunlock(&rw);
        usleep(2000);
    }
    return NULL;
}

int main(void) {
    rw_init(&rw);
    pthread_t rth[NUM_READERS], wth[NUM_WRITERS];

    for (int i = 0; i < NUM_READERS; i++) pthread_create(&rth[i], NULL, reader_thread, NULL);
    for (int i = 0; i < NUM_WRITERS; i++) pthread_create(&wth[i], NULL, writer_thread, NULL);

    for (int i = 0; i < NUM_READERS; i++) pthread_join(rth[i], NULL);
    for (int i = 0; i < NUM_WRITERS; i++) pthread_join(wth[i], NULL);

    pthread_mutex_destroy(&rw.mtx);
    pthread_cond_destroy(&rw.read_cv);
    pthread_cond_destroy(&rw.write_cv);
    printf("Completed. Final data: %d\n", shared_data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <assert.h>

#define NUM_READERS 4
#define NUM_WRITERS 2
#define WRITER_LOOPS 5
#define READER_LOOPS 10

typedef struct {
