    pthread_cond_t ok_to_read;
    pthread_cond_t ok_to_write;
    int readers;
    int writers;
    int waiting_writers;
} wp_lock_t;

static wp_lock_t lock;
static int value_a = 0;
static int value_b = 0;

static void lock_init(wp_lock_t *l) {
    pthread_mutex_init(&l->mtx, NULL);
