    l->waiting_writers = 0;
}

static void read_lock(wp_lock_t *l) {
    pthread_mutex_lock(&l->mtx);
    while (l->writers > 0 || l->waiting_writers > 0) {
        pthread_cond_wait(&l->ok_to_read, &l->mtx);
    }
    l->readers++;
    pthread_mutex_unlock(&l->mtx);
}

static void read_unlock(wp_lock_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->readers--;
    if (l->readers == 0 && l->waiting_writers > 0) {
        pthread_cond_signal(&l->ok_to_write);
    }
    pthread_mutex_unlock(&l->mtx);
}

static void write_lock(wp_lock_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->waiting_writers++;
    while (l->readers > 0 || l->writers > 0) {
        pthread_cond_wait(&l->ok_to_write, &l->mtx);
    }
    l->waiting_writers--;
    l->writers = 1;
    pthread_mutex_unlock(&l->mtx);
}

static void write_unlock(wp_lock_t *l) {
    pthread_mutex_lock(&l->mtx);
    l->writers = 0;
    if (l->waiting_writers > 0) {
        pthread_cond_signal(&l->ok_to_write);
    } else {
        pthread_cond_broadcast(&l->ok_to_read);
    }
    pthread_mutex_unlock(&l->mtx);
}

static void *reader(void *arg) {
    (void)arg;
    for (int i = 0; i < READER_LOOPS; i++) {
        read_lock(&lock);
        int a = value_a;
        int b = value_b;
        assert(b == a * 2);
        read_unlock(&lock);
        usleep(1000);
    }
    return NULL;
}

static void *writer(void *arg) {
    (void)arg;
    for (int i = 0; i < WRITER_LOOPS; i++) {
        write_lock(&lock);
        value_a++;
        value_b = value_a * 2;
        write_unlock(&lock);
        usleep(2000);
    }
    return NULL;
}

int main(void) {
    lock_init(&lock);
    pthread_t r[NUM_READERS], w[NUM_WRITERS];

    for (int i = 0; i < NUM_READERS; i++) pthread_create(&r[i], NULL, reader, NULL);
    for (int i = 0; i < NUM_WRITERS; i++) pthread_create(&w[i], NULL, writer, NULL);

    for (int i = 0; i < NUM_READERS; i++) pthread_join(r[i], NULL);
    for (int i = 0; i < NUM_WRITERS; i++) pthread_join(w[i], NULL);

    pthread_mutex_destroy(&lock.mtx);
    pthread_cond_destroy(&lock.ok_to_read);
    pthread_cond_destroy(&lock.ok_to_write);
    printf("Invariants verified. A=%d, B=%d\n", value_a, value_b);
    return 0;
}

