#include <stdio.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int threshold;
    int count;
    int cycle;
} custom_barrier_t;

static void barrier_init(custom_barrier_t *b, int count) {
    pthread_mutex_init(&b->mutex, NULL);
    pthread_cond_init(&b->cond, NULL);
    b->threshold = count;
    b->count = 0;
    b->cycle = 0;
}

static void barrier_wait(custom_barrier_t *b) {
    pthread_mutex_lock(&b->mutex);
    int current_cycle = b->cycle;
    b->count++;
    if (b->count == b->threshold) {
        b->cycle++;
        b->count = 0;
        pthread_cond_broadcast(&b->cond);
    } else {
        while (current_cycle == b->cycle) {
            pthread_cond_wait(&b->cond, &b->mutex);
        }
    }
    pthread_mutex_unlock(&b->mutex);
}

static void barrier_destroy(custom_barrier_t *b) {
    pthread_mutex_destroy(&b->mutex);
    pthread_cond_destroy(&b->cond);
}

#define NUM_THREADS 4
static custom_barrier_t barrier;

static void *thread_func(void *arg) {
    (void)arg;
    barrier_wait(&barrier);
    barrier_wait(&barrier);
    return NULL;
}

int main(void) {
    pthread_t threads[NUM_THREADS];
    barrier_init(&barrier, NUM_THREADS);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    barrier_destroy(&barrier);
    return 0;
}

