#define BARRIER_SERIAL_THREAD 1
#define NUM_THREADS 4

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int threshold;
    int count;
    int cycle;
} leader_barrier_t;

static void leader_barrier_init(leader_barrier_t *b, int count) {
    pthread_mutex_init(&b->mutex, NULL);
    pthread_cond_init(&b->cond, NULL);
    b->threshold = count;
    b->count = 0;
    b->cycle = 0;
}

static int leader_barrier_wait(leader_barrier_t *b) {
    pthread_mutex_lock(&b->mutex);
    int current_cycle = b->cycle;
    b->count++;
    if (b->count == b->threshold) {
        b->cycle++;
        b->count = 0;
        pthread_cond_broadcast(&b->cond);
        pthread_mutex_unlock(&b->mutex);
        return BARRIER_SERIAL_THREAD;
    }
    while (current_cycle == b->cycle) {
        pthread_cond_wait(&b->cond, &b->mutex);
    }
    pthread_mutex_unlock(&b->mutex);
    return 0;
}

static void leader_barrier_destroy(leader_barrier_t *b) {
    pthread_mutex_destroy(&b->mutex);
    pthread_cond_destroy(&b->cond);
}

static leader_barrier_t barrier;
static int leader_counts[2] = {0, 0};

static void *worker(void *arg) {
    (void)arg;
    for (int phase = 0; phase < 2; phase++) {
        int res = leader_barrier_wait(&barrier);
        if (res == BARRIER_SERIAL_THREAD) {
            leader_counts[phase]++;
        }
    }
    return NULL;
}

int main(void) {
    pthread_t threads[NUM_THREADS];
    leader_barrier_init(&barrier, NUM_THREADS);

    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_create(&threads[i], NULL, worker, NULL);
    }
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    leader_barrier_destroy(&barrier);
    return 0;
}

#include <stdio.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    int value;
} MonitorCounter;

static void counter_init(MonitorCounter *c, int initial_val) {
    pthread_mutex_init(&c->lock, NULL);
    pthread_cond_init(&c->cond, NULL);
    c->value = initial_val;
}

static void counter_dec(MonitorCounter *c) {
    pthread_mutex_lock(&c->lock);
    c->value--;
    if (c->value == 0) {
        pthread_cond_broadcast(&c->cond);
    }
    pthread_mutex_unlock(&c->lock);
}

static void counter_wait_until_zero(MonitorCounter *c) {
    pthread_mutex_lock(&c->lock);
    while (c->value != 0) {
        pthread_cond_wait(&c->cond, &c->lock);
    }
    pthread_mutex_unlock(&c->lock);
}

static void counter_destroy(MonitorCounter *c) {
    pthread_mutex_destroy(&c->lock);
    pthread_cond_destroy(&c->cond);
}

static MonitorCounter g_counter;

static void *dec_worker(void *arg) {
    (void)arg;
    counter_dec(&g_counter);
    return NULL;
}

int main(void) {
    pthread_t threads[4];
    counter_init(&g_counter, 4);

    for (int i = 0; i < 4; i++) {
        pthread_create(&threads[i], NULL, dec_worker, NULL);
    }

    counter_wait_until_zero(&g_counter);

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], NULL);
    }
    counter_destroy(&g_counter);
    return 0;
}

#include <stdio.h>
#include <pthread.h>

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t zero_cond;
    pthread_cond_t positive_cond;
    int value;
} SafeCounter;

static void safe_counter_init(SafeCounter *c, int init_val) {
    pthread_mutex_init(&c->lock, NULL);
    pthread_cond_init(&c->zero_cond, NULL);
    pthread_cond_init(&c->positive_cond, NULL);
    c->value = init_val;
}

static void safe_counter_inc(SafeCounter *c) {
    pthread_mutex_lock(&c->lock);
    c->value++;
    pthread_cond_signal(&c->positive_cond);
    pthread_mutex_unlock(&c->lock);
}

static void safe_counter_dec(SafeCounter *c) {
    pthread_mutex_lock(&c->lock);
    while (c->value == 0) {
        pthread_cond_wait(&c->positive_cond, &c->lock);
    }
    c->value--;
    if (c->value == 0) {
        pthread_cond_broadcast(&c->zero_cond);
    }
    pthread_mutex_unlock(&c->lock);
}

static void safe_counter_wait_zero(SafeCounter *c) {
    pthread_mutex_lock(&c->lock);
    while (c->value != 0) {
        pthread_cond_wait(&c->zero_cond, &c->lock);
    }
    pthread_mutex_unlock(&c->lock);
}

static void safe_counter_destroy(SafeCounter *c) {
    pthread_mutex_destroy(&c->lock);
    pthread_cond_destroy(&c->zero_cond);
    pthread_cond_destroy(&c->positive_cond);
}

static SafeCounter counter;

static void *watcher(void *arg) {
    (void)arg;
    safe_counter_wait_zero(&counter);
    return NULL;
}

static void *worker(void *arg) {
    (void)arg;
    safe_counter_dec(&counter);
    return NULL;
}

int main(void) {
    pthread_t watchers[2];
    pthread_t workers[2];

    safe_counter_init(&counter, 2);

    pthread_create(&watchers[0], NULL, watcher, NULL);
    pthread_create(&watchers[1], NULL, watcher, NULL);

    pthread_create(&workers[0], NULL, worker, NULL);
    pthread_create(&workers[1], NULL, worker, NULL);

    for (int i = 0; i < 2; i++) {
        pthread_join(watchers[i], NULL);
        pthread_join(workers[i], NULL);
    }

    safe_counter_destroy(&counter);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define ROUNDS 10

enum Ingredient {
    TOBACCO = 0,
    PAPER = 1,
    MATCHES = 2
};

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t agent_cv;
    pthread_cond_t smoker_cv[3];
    int table_missing; /* ingredient needed by the matching smoker (-1 if empty) */
    int stop;
} Table;

static Table table = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .agent_cv = PTHREAD_COND_INITIALIZER,
    .smoker_cv = {
        PTHREAD_COND_INITIALIZER,
        PTHREAD_COND_INITIALIZER,
        PTHREAD_COND_INITIALIZER
    },
    .table_missing = -1,
    .stop = 0
};

static void *agent_thread(void *arg) {
    (void)arg;
    for (int i = 0; i < ROUNDS; i++) {
        pthread_mutex_lock(&table.lock);
        while (table.table_missing != -1) {
            pthread_cond_wait(&table.agent_cv, &table.lock);
        }

        /* missing ingredient corresponds to the smoker who can make a cigarette */
        table.table_missing = rand() % 3;
        pthread_cond_signal(&table.smoker_cv[table.table_missing]);
        pthread_mutex_unlock(&table.lock);
    }

    pthread_mutex_lock(&table.lock);
    while (table.table_missing != -1) {
        pthread_cond_wait(&table.agent_cv, &table.lock);
    }
    table.stop = 1;
    for (int i = 0; i < 3; i++) {
        pthread_cond_signal(&table.smoker_cv[i]);
    }
    pthread_mutex_unlock(&table.lock);
    return NULL;
}

static void *smoker_thread(void *arg) {
    int my_ingredient = (int)(intptr_t)arg;

    while (1) {
        pthread_mutex_lock(&table.lock);
        while (table.table_missing != my_ingredient && !table.stop) {
            pthread_cond_wait(&table.smoker_cv[my_ingredient], &table.lock);
        }
        if (table.stop && table.table_missing != my_ingredient) {
            pthread_mutex_unlock(&table.lock);
            break;
        }

        table.table_missing = -1;
        pthread_cond_signal(&table.agent_cv);
        pthread_mutex_unlock(&table.lock);
    }
    return NULL;
}

int main(void) {
    srand(42);
    pthread_t smokers[3];
    pthread_t agent;

    for (intptr_t i = 0; i < 3; i++) {
        if (pthread_create(&smokers[i], NULL, smoker_thread, (void *)i) != 0) {
            return 1;
        }
    }

    if (pthread_create(&agent, NULL, agent_thread, NULL) != 0) {
        return 1;
    }

    pthread_join(agent, NULL);
    for (int i = 0; i < 3; i++) {
        pthread_join(smokers[i], NULL);
    }

    pthread_mutex_destroy(&table.lock);
    pthread_cond_destroy(&table.agent_cv);
    for (int i = 0; i < 3; i++) {
        pthread_cond_destroy(&table.smoker_cv[i]);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <pthread.h>

#define ROUNDS 10

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    bool has_tobacco;
    bool has_paper;
    bool has_matches;
    bool done;
} Table;

static Table table = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .cond = PTHREAD_COND_INITIALIZER,
    .has_tobacco = false,
    .has_paper = false,
    .has_matches = false,
    .done = false
};

static void *agent_func(void *arg) {
    (void)arg;
    for (int i = 0; i < ROUNDS; i++) {
        pthread_mutex_lock(&table.lock);
        while (table.has_tobacco || table.has_paper || table.has_matches) {
            pthread_cond_wait(&table.cond, &table.lock);
        }

        int choice = rand() % 3;
        if (choice == 0) {
            table.has_paper = true;
            table.has_matches = true;
        } else if (choice == 1) {
            table.has_tobacco = true;
            table.has_matches = true;
        } else {
            table.has_tobacco = true;
            table.has_paper = true;
        }

        pthread_cond_broadcast(&table.cond);
        pthread_mutex_unlock(&table.lock);
    }

    pthread_mutex_lock(&table.lock);
    while (table.has_tobacco || table.has_paper || table.has_matches) {
        pthread_cond_wait(&table.cond, &table.lock);
    }
    table.done = true;
    pthread_cond_broadcast(&table.cond);
    pthread_mutex_unlock(&table.lock);
    return NULL;
}

static void *smoker_func(void *arg) {
    int item = (int)(intptr_t)arg; /* 0: owns tobacco, 1: owns paper, 2: owns matches */

    while (1) {
        pthread_mutex_lock(&table.lock);
        while (!table.done) {
            if (item == 0 && table.has_paper && table.has_matches) {
                break;
            }
            if (item == 1 && table.has_tobacco && table.has_matches) {
                break;
            }
            if (item == 2 && table.has_tobacco && table.has_paper) {
                break;
            }
            pthread_cond_wait(&table.cond, &table.lock);
        }

        if (table.done && !(table.has_tobacco || table.has_paper || table.has_matches)) {
            pthread_mutex_unlock(&table.lock);
            break;
        }

        /* Consume the two items on the table */
        table.has_tobacco = false;
        table.has_paper = false;
        table.has_matches = false;

        pthread_cond_broadcast(&table.cond);
        pthread_mutex_unlock(&table.lock);
    }
    return NULL;
}

