#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_READERS 5
#define NUM_WRITERS 2
#define OPS_PER_THREAD 5

typedef struct {
    pthread_mutex_t count_lock;
    pthread_mutex_t write_lock;
    int read_count;
    int shared_data;
} RWState;

static RWState rw = {
    .count_lock = PTHREAD_MUTEX_INITIALIZER,
    .write_lock = PTHREAD_MUTEX_INITIALIZER,
    .read_count = 0,
    .shared_data = 0
};

static void *reader_thread(void *arg) {
    (void)arg;
    for (int i = 0; i < OPS_PER_THREAD; i++) {
        pthread_mutex_lock(&rw.count_lock);
        rw.read_count++;
        if (rw.read_count == 1) {
            pthread_mutex_lock(&rw.write_lock);
        }
        pthread_mutex_unlock(&rw.count_lock);

        /* Read operation */
        int val = rw.shared_data;
        (void)val;

        pthread_mutex_lock(&rw.count_lock);
        rw.read_count--;
        if (rw.read_count == 0) {
            pthread_mutex_unlock(&rw.write_lock);
        }
        pthread_mutex_unlock(&rw.count_lock);
    }
    return NULL;
}

static void *writer_thread(void *arg) {
    (void)arg;
    for (int i = 0; i < OPS_PER_THREAD; i++) {
        pthread_mutex_lock(&rw.write_lock);
        rw.shared_data++;
        pthread_mutex_unlock(&rw.write_lock);
    }
    return NULL;
}

int main(void) {
    pthread_t readers[NUM_READERS];
    pthread_t writers[NUM_WRITERS];

    for (int i = 0; i < NUM_READERS; i++) {
        if (pthread_create(&readers[i], NULL, reader_thread, NULL) != 0) {
            return 1;
        }
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        if (pthread_create(&writers[i], NULL, writer_thread, NULL) != 0) {
            return 1;
        }
    }

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_join(readers[i], NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_join(writers[i], NULL);
    }

    pthread_mutex_destroy(&rw.count_lock);
    pthread_mutex_destroy(&rw.write_lock);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_READERS 4
#define NUM_WRITERS 2
#define ROUNDS 4

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t can_read;
    pthread_cond_t can_write;
    int active_readers;
    int waiting_readers;
    int writer_active;
    int shared_value;
} RWMonitor;

static RWMonitor mon = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .can_read = PTHREAD_COND_INITIALIZER,
    .can_write = PTHREAD_COND_INITIALIZER,
    .active_readers = 0,
    .waiting_readers = 0,
    .writer_active = 0,
    .shared_value = 0
};

static void *reader(void *arg) {
    (void)arg;
    for (int i = 0; i < ROUNDS; i++) {
        pthread_mutex_lock(&mon.lock);
        mon.waiting_readers++;
        while (mon.writer_active) {
            pthread_cond_wait(&mon.can_read, &mon.lock);
        }
        mon.waiting_readers--;
        mon.active_readers++;
        pthread_mutex_unlock(&mon.lock);

        /* Read value */
        pthread_mutex_lock(&mon.lock);
        int val = mon.shared_value;
        (void)val;
        mon.active_readers--;
        if (mon.active_readers == 0) {
            pthread_cond_signal(&mon.can_write);
        }
        pthread_mutex_unlock(&mon.lock);
    }
    return NULL;
}

static void *writer(void *arg) {
    (void)arg;
    for (int i = 0; i < ROUNDS; i++) {
        pthread_mutex_lock(&mon.lock);
        /* Reader preference: wait while any reader is active OR waiting */
        while (mon.writer_active || mon.active_readers > 0 || mon.waiting_readers > 0) {
            pthread_cond_wait(&mon.can_write, &mon.lock);
        }
        mon.writer_active = 1;
        mon.shared_value++;
        mon.writer_active = 0;

        if (mon.waiting_readers > 0) {
            pthread_cond_broadcast(&mon.can_read);
        } else {
            pthread_cond_signal(&mon.can_write);
        }
        pthread_mutex_unlock(&mon.lock);
    }
    return NULL;
}

int main(void) {
    pthread_t readers[NUM_READERS];
    pthread_t writers[NUM_WRITERS];

    for (int i = 0; i < NUM_READERS; i++) {
        if (pthread_create(&readers[i], NULL, reader, NULL) != 0) {
            return 1;
        }
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        if (pthread_create(&writers[i], NULL, writer, NULL) != 0) {
            return 1;
        }
    }

    for (int i = 0; i < NUM_READERS; i++) {
        pthread_join(readers[i], NULL);
    }
    for (int i = 0; i < NUM_WRITERS; i++) {
        pthread_join(writers[i], NULL);
    }

    pthread_mutex_destroy(&mon.lock);
    pthread_cond_destroy(&mon.can_read);
    pthread_cond_destroy(&mon.can_write);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define ARRAY_SIZE 100000
#define NUM_THREADS 4

typedef struct {
    const int *array;
    size_t start;
    size_t end;
    long long partial_sum;
} WorkerArg;

static void *sum_worker(void *arg) {
    WorkerArg *wa = (WorkerArg *)arg;
    long long sum = 0;
    for (size_t i = wa->start; i < wa->end; i++) {
        sum += wa->array[i];
    }
    wa->partial_sum = sum;
    return NULL;
}

int main(void) {
    int *arr = malloc(sizeof(int) * ARRAY_SIZE);
    if (!arr) {
        return 1;
    }
    for (size_t i = 0; i < ARRAY_SIZE; i++) {
        arr[i] = 1;
    }

    pthread_t threads[NUM_THREADS];
    WorkerArg args[NUM_THREADS];
    size_t chunk = ARRAY_SIZE / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS; i++) {
        args[i].array = arr;
        args[i].start = (size_t)i * chunk;
        args[i].end = (i == NUM_THREADS - 1) ? ARRAY_SIZE : args[i].start + chunk;
        args[i].partial_sum = 0;
        if (pthread_create(&threads[i], NULL, sum_worker, &args[i]) != 0) {
            free(arr);
            return 1;
        }
    }

    long long total_sum = 0;
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
        total_sum += args[i].partial_sum;
    }

    free(arr);
    return (total_sum == ARRAY_SIZE) ? 0 : 2;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdalign.h>
#include <pthread.h>

#define ARRAY_SIZE 100000
#define NUM_THREADS 4

typedef struct {
    alignas(64) long long partial_sum;
    const int *array;
    size_t start;
    size_t end;
} ThreadSlot;

typedef struct {
    pthread_mutex_t lock;
    long long total;
} GlobalAcc;

static GlobalAcc acc = {
    .lock = PTHREAD_MUTEX_INITIALIZER,
    .total = 0
};

static void *worker_func(void *arg) {
    ThreadSlot *slot = (ThreadSlot *)arg;
    long long local_sum = 0;
    for (size_t i = slot->start; i < slot->end; i++) {
        local_sum += slot->array[i];
    }
    slot->partial_sum = local_sum;

    pthread_mutex_lock(&acc.lock);
    acc.total += local_sum;
    pthread_mutex_unlock(&acc.lock);
    return NULL;
}

int main(void) {
    int *arr = malloc(sizeof(int) * ARRAY_SIZE);
    if (!arr) {
        return 1;
    }
    for (size_t i = 0; i < ARRAY_SIZE; i++) {
        arr[i] = 2;
    }

    pthread_t threads[NUM_THREADS];
    ThreadSlot slots[NUM_THREADS];
    size_t chunk = ARRAY_SIZE / NUM_THREADS;

    for (int i = 0; i < NUM_THREADS; i++) {
        slots[i].array = arr;
        slots[i].start = (size_t)i * chunk;
        slots[i].end = (i == NUM_THREADS - 1) ? ARRAY_SIZE : slots[i].start + chunk;
        slots[i].partial_sum = 0;
        if (pthread_create(&threads[i], NULL, worker_func, &slots[i]) != 0) {
            free(arr);
            return 1;
        }
    }

    long long from_partials = 0;
    for (int i = 0; i < NUM_THREADS; i++) {
        pthread_join(threads[i], NULL);
        from_partials += slots[i].partial_sum;
    }

    pthread_mutex_destroy(&acc.lock);
    long long expected = (long long)ARRAY_SIZE * 2;
    int status = (acc.total == expected && from_partials == expected) ? 0 : 2;
    free(arr);
    return status;
}

