}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pthread.h>

#define NUM_PHILOSOPHERS 5
#define MAX_ACTIVE 4
#define EAT_COUNT 3

typedef struct {
    pthread_mutex_t waiter_lock;
    pthread_cond_t waiter_cond;
    int active_diners;
    pthread_mutex_t forks[NUM_PHILOSOPHERS];
} DiningRoom;

static DiningRoom room = {
    .waiter_lock = PTHREAD_MUTEX_INITIALIZER,
    .waiter_cond = PTHREAD_COND_INITIALIZER,
    .active_diners = 0
};

static void *philosopher(void *arg) {
    int id = (int)(intptr_t)arg;
    int left = id;
    int right = (id + 1) % NUM_PHILOSOPHERS;

    for (int i = 0; i < EAT_COUNT; i++) {
        /* Ask arbitrator for permission */
        pthread_mutex_lock(&room.waiter_lock);
        while (room.active_diners >= MAX_ACTIVE) {
            pthread_cond_wait(&room.waiter_cond, &room.waiter_lock);
        }
        room.active_diners++;
        pthread_mutex_unlock(&room.waiter_lock);

        /* Acquire left then right fork */
        pthread_mutex_lock(&room.forks[left]);
        pthread_mutex_lock(&room.forks[right]);

        /* Eating */

        pthread_mutex_unlock(&room.forks[right]);
        pthread_mutex_unlock(&room.forks[left]);

        /* Inform arbitrator of release */
        pthread_mutex_lock(&room.waiter_lock);
        room.active_diners--;
        pthread_cond_signal(&room.waiter_cond);
        pthread_mutex_unlock(&room.waiter_lock);
    }
    return NULL;
}

int main(void) {
    pthread_t phils[NUM_PHILOSOPHERS];

    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_mutex_init(&room.forks[i], NULL);
    }

    for (intptr_t i = 0; i < NUM_PHILOSOPHERS; i++) {
        if (pthread_create(&phils[i], NULL, philosopher, (void *)i) != 0) {
            return 1;
        }
    }

    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_join(phils[i], NULL);
    }

    pthread_mutex_destroy(&room.waiter_lock);
    pthread_cond_destroy(&room.waiter_cond);
    for (int i = 0; i < NUM_PHILOSOPHERS; i++) {
        pthread_mutex_destroy(&room.forks[i]);
    }
    return 0;
}

