#include <pthread.h>
#include <unistd.h>

typedef struct {
    int gate_number;
    int override_auth;
    pthread_mutex_t *gate_lock;
} gate_job_t;

void* operate_gate(void *arg) {
    gate_job_t *job = (gate_job_t*)arg;

    if (!job->override_auth) {
        printf("Gate %d: Unauthorized access attempt.\n", job->gate_number);
        pthread_mutex_unlock(job->gate_lock);
        return NULL;
    }

    pthread_mutex_lock(job->gate_lock);
    printf("Gate %d: Opening securely.\n", job->gate_number);
    pthread_mutex_unlock(job->gate_lock);
    return NULL;
}

int main(void) {
    pthread_t t;
    pthread_mutex_t m;
    pthread_mutex_init(&m, NULL);

    gate_job_t job = { .gate_number = 3, .override_auth = 0, .gate_lock = &m };

    pthread_create(&t, NULL, operate_gate, &job);
    pthread_join(t, NULL);

    pthread_mutex_destroy(&m);
    return 0;
}

